{
  "title": "Discussion on tax filing, domain purchase, and app monetization",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Complications with tax filing and calculator usage",
      "claims": [
        {
          "text": "Using aunt Sveta's help allowed the user to correctly refile and pay about 1000 UAH instead of all fines",
          "evidence": [1]
        },
        {
          "text": "The inspector had not reviewed the user's declarations for 1.5 years and was later reprimanded",
          "evidence": [1]
        },
        {
          "text": "The tax calculation process is error‑prone, especially regarding which column to subtract which number",
          "evidence": [8]
        },
        {
          "text": "Quarterly reports must be filed and taxes paid correctly",
          "evidence": [7]
        },
        {
          "text": "The calculator only works with Ukrainian‑currency FOPs, requiring conversion based on daily exchange rates",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Considerations about buying a domain",
      "claims": [
        {
          "text": "One participant suggests buying a calculator first before affording a domain",
          "evidence": [4]
        },
        {
          "text": "Another participant doubts buying a domain due to its low value",
          "evidence": [9, 10]
        }
      ]
    },
    {
      "id": "app-monetization",
      "title": "Ideas and skepticism about earning from a cross‑platform app",
      "claims": [
        {
          "text": "Web platforms are less profitable than Android/iOS and have poor SEO and traffic",
          "evidence": [11]
        },
        {
          "text": "Successful projects have very fast delivery (under a week) and use a cross‑platform stack like Flutter",
          "evidence": [12]
        },
        {
          "text": "There is skepticism that anyone would pay 299 UAH for the app without verified demand",
          "evidence": [20, 22]
        },
        {
          "text": "The app claims to fetch USD/UAH rates every 5 minutes and perform calculations locally in the browser",
          "evidence": [29]
        },
        {
          "text": "The source code and password for a 100 % discount are presumed easy to find or crack",
          "evidence": [21, 28]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is the source code or password for the app searchable and accessible?",
      "evidence": [21]
    }
  ]
}
